import json, time, urllib.request, urllib.error, sys
from datetime import datetime, timezone
from decimal import Decimal
B="http://localhost:8080"
tok=None
log={}
def note(k): log[k]=log.get(k,0)+1
def get(path):
    global tok
    for attempt in range(200):
        if tok is None:
            r=urllib.request.Request(B+"/token",method="POST")
            tok=json.load(urllib.request.urlopen(r))["token"]
        req=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            with urllib.request.urlopen(req) as r:
                return r.status, json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors="replace")
            note(f"http{e.code}")
            if e.code==404: return 404,None
            if e.code==401 or (e.code==403): tok=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                print("429",ra,body[:100],file=sys.stderr)
                time.sleep(w+0.1); continue
            print(e.code,body[:150],dict(e.headers),file=sys.stderr)
            if "token" in body.lower() or "expire" in body.lower(): tok=None
            time.sleep(1); continue
        except (urllib.error.URLError, json.JSONDecodeError, ConnectionError) as e:
            note("neterr"); print("err",e,file=sys.stderr); time.sleep(1)
    raise RuntimeError(path)
pages={}
p=1
while p:
    s,d=get(f"/orders?page={p}")
    pages[p]=d
    p=None
    if d["next"]: p=int(d["next"].split("page=")[1].split("&")[0])
tp=pages[1]["total_pages"]
print("pages fetched",len(pages),"total_pages",tp,file=sys.stderr)
seen={}; dups=0; allitems=0
for n in sorted(pages):
    for o in pages[n]["items"]:
        allitems+=1
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: print("DUP DIFFERS",seen[o["id"]],o,file=sys.stderr)
        else: seen[o["id"]]=o
cust={}
def cu(i):
    if i not in cust:
        s,d=get(f"/customers/{i}"); cust[i]=d
    return cust[i]
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
reg={"north":0,"south":0,"east":0,"west":0}; cnt=0; stat=set(); missing=[]
for o in seen.values():
    stat.add(o["status"])
    if o["status"]!="shipped": continue
    ts=o["placed_at"]
    dt=datetime.fromisoformat(ts.replace("Z","+00:00"))
    if dt.tzinfo is None: print("naive",ts,file=sys.stderr); dt=dt.replace(tzinfo=timezone.utc)
    dt=dt.astimezone(timezone.utc)
    if not (lo<=dt<hi): continue
    c=cu(o["customer_id"])
    if c is None: missing.append(o); continue
    a=o["amount_cents"]*(100-c["discount_pct"])
    v=(a+50)//100  # half up, integer exact
    reg[c["region"]]+=v; cnt+=1
res={"total_cents":sum(reg.values()),"order_count":cnt,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res); print("items",allitems,"distinct",len(seen),"statuses",stat,"missing",missing,"log",log,"customers",len(cust))
EOF
python3 -I /tmp/recon/run.py

